INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind elektrische Anlagen nur für Hochspannung gedacht?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Niederspannung"}, {"text": "Ja", "correct": false, "because": "Breiterer Einsatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgen elektrische Anlagen in einem Betrieb?', 3, '[{"text": "Stromversorgung bereitstellen", "correct": true, "because": "Energie für Geräte"}, {"text": "Daten speichern", "correct": false, "because": "Andere Funktion"}, {"text": "Netzwerk verbinden", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zu elektrischen Anlagen?', 5, '[{"text": "Verteiler", "correct": true, "because": "Stromverteilung"}, {"text": "Betriebsmittel", "correct": true, "because": "Verbraucher"}, {"text": "Papierdokumente", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Elektrische Anlagen müssen regelmäßig geprüft werden. b) Sie sind nur für Beleuchtung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Viele Zwecke"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei elektrischen Anlagen?', 4, '[{"text": "Sicherheitsprüfungen", "correct": false, "because": "Pflicht"}, {"text": "Normen", "correct": false, "because": "VDE entscheidend"}, {"text": "Kabeldesign", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob elektrische Anlagen nur stationär sind?', 2, '[{"text": "Nein", "correct": true, "because": "Auch mobil"}, {"text": "Ja", "correct": false, "because": "Ortsveränderlich möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Norm regelt elektrische Anlagen?', 3, '[{"text": "DIN VDE 0100", "correct": true, "because": "Niederspannungsanlagen"}, {"text": "ISO 9001", "correct": false, "because": "Qualitätsmanagement"}, {"text": "DIN 18015", "correct": false, "because": "Wohngebäude spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Sicherheitsmaßnahmen sind bei elektrischen Anlagen wichtig?', 5, '[{"text": "Schutzleiter", "correct": true, "because": "Erdung"}, {"text": "Fehlerstromschutzschalter", "correct": true, "because": "Personenschutz"}, {"text": "Papierisolierung", "correct": false, "because": "Ineffektiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Elektrische Anlagen müssen DGUV V3 entsprechen. b) Sie sind wartungsfrei. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wartung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korbreken"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für elektrische Anlagen?', 4, '[{"text": "Elektrofachkraft", "correct": false, "because": "Prüfung nötig"}, {"text": "Stromkreise", "correct": false, "because": "Grundstruktur"}, {"text": "Dekoration", "correct": true, "because": "Kein technischer Zweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Müssen elektrische Anlagen vor Inbetriebnahme geprüft werden?', 2, '[{"text": "Ja", "correct": true, "because": "Sicherheitsvorschrift"}, {"text": "Nein", "correct": false, "because": "Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von elektrischen Anlagen gibt es?', 4, '[{"text": "Stationäre", "correct": true, "because": "Ortsfest"}, {"text": "Ortsveränderliche", "correct": true, "because": "Mobil"}, {"text": "Papierbasierte", "correct": false, "because": "Nicht elektrisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass elektrische Anlagen keine Prüfprotokolle brauchen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Dokumentation Pflicht"}, {"text": "Ja", "correct": false, "because": "VDE 0100-600"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei elektrischen Anlagen?', 3, '[{"text": "Sicherheit", "correct": true, "because": "Personenschutz"}, {"text": "Farbcodierung", "correct": false, "because": "Sekundär"}, {"text": "Kosten", "correct": false, "because": "Sicherheit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Elektrische Anlagen müssen VDE-Normen entsprechen. b) Sie sind nur für IT-Geräte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Viele Zwecke"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken gibt es bei elektrischen Anlagen?', 5, '[{"text": "Stromschlag", "correct": true, "because": "Personengefahr"}, {"text": "Brandgefahr", "correct": true, "because": "Kurzschluss"}, {"text": "Papierverlust", "correct": false, "because": "Kein Risiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei elektrischen Anlagen unwichtig?', 3, '[{"text": "Schutzmaßnahmen", "correct": false, "because": "Sicherheit nötig"}, {"text": "Prüffristen", "correct": false, "because": "DGUV V3"}, {"text": "Optisches Design", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Müssen elektrische Anlagen regelmäßig gewartet werden?', 3, '[{"text": "Ja", "correct": true, "because": "Betriebssicherheit"}, {"text": "Nein", "correct": false, "because": "Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob elektrische Anlagen nur von Fachkräften installiert werden dürfen?', 2, '[{"text": "Ja", "correct": true, "because": "Elektrofachkraft nötig"}, {"text": "Nein", "correct": false, "because": "Vorschrift"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für elektrische Anlagen zentral?', 4, '[{"text": "Stromversorgung", "correct": true, "because": "Grundfunktion"}, {"text": "Papierdokumentation", "correct": false, "because": "Sekundär"}, {"text": "Manuelle Steuerung", "correct": false, "because": "Automatisierung möglich"}]');
